package com.cestasdamel.erp.repository; import com.cestasdamel.erp.model.BasketTemplate; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType; import java.util.*;
public interface BasketTemplateRepository extends JpaRepository<BasketTemplate,Long>{ @EntityGraph(attributePaths={"products","products.product","materials","materials.material"}) @Query("select distinct b from BasketTemplate b where b.deletedAt is null order by b.name") List<BasketTemplate> findAllDetailed(); @EntityGraph(attributePaths={"products","products.product","materials","materials.material"}) @Query("select distinct b from BasketTemplate b where b.id=:id and b.deletedAt is null") Optional<BasketTemplate> findDetailed(@Param("id") Long id); @Lock(LockModeType.PESSIMISTIC_WRITE) @EntityGraph(attributePaths={"products","products.product","materials","materials.material"}) @Query("select distinct b from BasketTemplate b where b.id=:id and b.deletedAt is null") Optional<BasketTemplate> lockDetailedById(@Param("id") Long id); @Query("select (count(bp)>0) from BasketProduct bp where bp.product.id=:id and bp.basket.deletedAt is null") boolean isProductUsed(@Param("id") Long id); @Query("select (count(bm)>0) from BasketMaterial bm where bm.material.id=:id and bm.basket.deletedAt is null") boolean isMaterialUsed(@Param("id") Long id); }
